def bubble_sort(values):
    output = list(values)
    for end in range(len(output) - 1, 0, -1):
        changed = False
        for index in range(end):
            if output[index] > output[index + 1]:
                output[index], output[index + 1] = output[index + 1], output[index]
                changed = True
        if not changed:
            break
    return output

